import{_ as p,a0 as s,w as a,s as u,I as n,x as o,a1 as r,A as l,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"Arch Linux 安裝捷徑：Evo/Lution | LCTT x X-CMD","titleTemplate":false,"description":"Arch Linux 安裝捷徑：Evo/Lution | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Arch Linux 安裝捷徑：Evo/Lution | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Arch Linux 安裝捷徑：Evo/Lution | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140919 How to install Arch Linux the easy way with Evo or Lution","title":"Arch Linux 安裝捷徑：Evo/Lution","tag":"201411","desc":""},"relativePath":"201411/20140919 How to install Arch Linux the easy way with Evo or Lution.md","filePath":"[post].md"}'),m={name:"201411/20140919 How to install Arch Linux the easy way with Evo or Lution.md"};function f(d,t,L,x,g,w){const i=s("Link");return a(),u("div",null,[t[24]||(t[24]=n("h1",{id:"arch-linux-安裝捷徑-evo-lution",tabindex:"-1"},[o("Arch Linux 安裝捷徑：Evo/Lution "),n("a",{class:"header-anchor",href:"#arch-linux-安裝捷徑-evo-lution","aria-label":"Permalink to “Arch Linux 安裝捷徑：Evo/Lution”"},"​")],-1)),t[25]||(t[25]=n("p",null,"有些人只體驗過Ubuntu或Mint的安裝，卻鼓起勇氣想要安裝Arch Linux，他們的學習道路是那樣的陡峭和嚴峻，安裝過程中半途而廢的人數可能要比順利過關的人多得多。如果你成功搭建並按你所需的配置好了Arch Linux，那麼它已經把你培養成了一個飽經風霜的Linux用户。",-1)),n("p",null,[t[1]||(t[1]=o("即使有",-1)),r(i,{href:"https://wiki.archlinux.org/"},{default:l(()=>[...t[0]||(t[0]=[o("可以幫助你的維基",-1)])]),_:1}),t[2]||(t[2]=o("為新手提供指南，對於那些想要征服Arch的人而言要求仍然太高。你需要至少熟悉諸如fdisk或mkfs之類的終端命令，並且聽過mc、nano或chroot這些，並努力掌握它們。這讓我回想起了10年前的Debian安裝。",-1))]),n("p",null,[t[4]||(t[4]=o("對於那些滿懷抱負而又缺乏知識的生靈，有一個叫",-1)),r(i,{href:"http://www.evolutionlinux.com/"},{default:l(()=>[...t[3]||(t[3]=[o("Evo/Lution Live ISO",-1)])]),_:1}),t[5]||(t[5]=o("的ISO鏡像格式安裝器可以拯救他們。即便它貌似像發行版一樣啓動，但它其實除了輔助安裝Arch Linux準系統之外啥都不幹。Evo/Lution是一個項目，它旨在通過提供Arch的簡單安裝方式來為Arch的增加更多的用户基數，就像為那些用户提供全面幫助和文檔的社區一樣。在這樣一個組合中，Evo是Live CD（不可安裝），而Lution是個安裝器本身。項目創立者看到了Arch及其衍生發行版的開發者和用户之間的巨大鴻溝，而想要在所有參與者之間構築一個身份平等的社區。",-1))]),t[26]||(t[26]=e('<p><img src="https://farm6.staticflickr.com/5559/15067088008_ecb221408c_z.jpg" alt=""></p><p>項目的軟件部分是命令列安裝器Lution-AIS，它負責解釋一個普通的純淨的Arch安裝過程中的每一步。安裝完畢後，你將獲得Arch提供的沒有從AUR添加任何東西的最新軟件或其它任何自定義的包。</p><p>啓動這個422MB大小的ISO鏡像後，一個由顯示在右邊的帶有選項快捷方式的Conky和一個左邊等待運行安裝器的LX-Terminal組成的工作區便呈現在我們眼前。</p><p><img src="https://farm6.staticflickr.com/5560/15067056888_6345c259db_z.jpg" alt=""></p><p>在通過右擊桌面或使用ALT-i啓動實際的安裝器後，一個寫滿了16個等待運行的任務列表就出現在你面前了。除非你知道你在做什麼，否則請將這些任務全部運行一遍。你可以一次運行，也可以進行選擇，如1 3 6，或者1-4，也可以一次將它們全部運行，輸入1-16。大多數步驟需要‘y’，即‘yes’，來確認，敲擊回車即可。在此期間，你有足夠的時間來閲讀安裝指南，它可以通過ALT-g來打開。當然，你也可以出去溜達一圈再回來。</p><p><img src="https://farm4.staticflickr.com/3868/15253227082_5e7219f72d_z.jpg" alt=""></p><p>這16個步驟分成“基礎安裝”和“桌面安裝”兩組。第一個組安裝主要關注本地化、分區，以及安裝啓動器。</p><p>安裝器帶領你穿越分區世界，你可以選擇使用gparted、gdisk，以及cfdisk。</p><p><img src="https://farm4.staticflickr.com/3873/15230603226_56bba60d28_z.jpg" alt=""></p><p><img src="https://farm4.staticflickr.com/3860/15253610055_e6a2a7a1cb_z.jpg" alt=""></p><p>創建完分區後（如，像截圖中所示，用gparted劃分/dev/sda1用於root，/dev/sda2用於swap），你可以在10個文件系統中選擇其中之一。在下一步中，你可以選擇內核（最新或長期支持LTS）和基礎系統。</p><p><img src="https://farm6.staticflickr.com/5560/15253610085_aa5a9557fb_z.jpg" alt=""></p><p>安裝完你喜愛的啓動加載器後，第一部分安裝就完成了，這大約需要花費12分鐘。這是在普通的Arch Linux中你第一次重啓進入系統所處之處。</p><p>在Lution的幫助下，繼續進入第二部分，在這一部分中將安裝Xorg、聲音和圖形驅動，然後進入桌面環境。</p><p><img src="https://farm4.staticflickr.com/3918/15066917430_c21e0f0a9e_z.jpg" alt=""></p><p>安裝器會檢測是否在VirtualBox中安裝，並且會自動為VM安裝並加載正確的通用驅動，然後相應地設置<strong>systemd</strong>。</p><p>在下一步中，你可以選擇KDE、Gnome、Cinnamon、LXDE、Englightenment、Mate或XFCE作為你的桌面環境。如果你不喜歡臃腫的桌面，你也可以試試這些窗口管理器：Awesome、Fluxbox、i3、IceWM、Openbox或PekWM。</p><p><img src="https://farm4.staticflickr.com/3874/15253610125_26f913be20_z.jpg" alt=""></p><p>在使用Cinnamon作為桌面環境的情況下，第二部分安裝將花費不到10分鐘的時間；而選擇KDE的話，因為要下載的東西多得多，所以花費的時間也會更長。</p><p>Lution-AIS在Cinnamon和Awesome上像個嫵媚的小妖精。在安裝完成並提示重啓後，它就帶我進入了我所渴望的環境。</p><p><img src="https://farm4.staticflickr.com/3885/15270946371_c2def59f37_z.jpg" alt=""></p><p>我要提出兩點批評：一是在安裝器要我選擇一個鏡像列表時，以及在創建fstab文件時。在這兩種情況下，它都另外開了一個終端，給出了一些文本信息提示。這讓我花了點時間才搞清楚，原來我得把它關了，安裝器才會繼續。在創建fstab後，它又會提示你，而你需要關閉終端，並在問你是否想要保存文件時回答‘是’。</p><p><img src="https://farm4.staticflickr.com/3874/15067056958_3bba63da60_z.jpg" alt=""></p><p>我碰到的第二個問題，可能與VirtualBox有關了。在啓動的時候，你可以看到沒有網絡被檢測到的提示信息。點擊頂部左邊的圖標，將會打開我們所使用的網絡管理器wicd。點擊“斷開”，然後再點擊“連接”並重啓安裝器，就可以讓它自動檢測到了。</p>',24)),n("p",null,[t[8]||(t[8]=o("Evo/Lution看起來是個有價值的項目，在這裏Lution工作一切順利，目前還沒有什麼可告訴社區的。他們開啓了一個全新的網站、論壇和維基，需要填充內容進去啊。所以，如果你喜歡這主意，加入",-1)),r(i,{href:"http://www.evolutionlinux.com/forums/"},{default:l(()=>[...t[6]||(t[6]=[o("他們的論壇",-1)])]),_:1}),t[9]||(t[9]=o("並告訴他們吧。本文中的ISO鏡像可以從",-1)),r(i,{href:"http://www.evolutionlinux.com/downloads.html"},{default:l(()=>[...t[7]||(t[7]=[o("此網站",-1)])]),_:1}),t[10]||(t[10]=o("下載。",-1))]),t[27]||(t[27]=n("hr",null,null,-1)),n("p",null,[t[12]||(t[12]=o("via: ",-1)),r(i,{href:"http://xmodulo.com/2014/09/install-arch-linux-easy-way-evolution.html"},{default:l(()=>[...t[11]||(t[11]=[o("http://xmodulo.com/2014/09/install-arch-linux-easy-way-evolution.html",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("作者：",-1)),r(i,{href:"http://xmodulo.com/author/ferdinand"},{default:l(()=>[...t[13]||(t[13]=[o("Ferdinand Thommes",-1)])]),_:1}),t[17]||(t[17]=o(" 譯者：",-1)),r(i,{href:"https://github.com/GOLinux"},{default:l(()=>[...t[14]||(t[14]=[o("GOLinux",-1)])]),_:1}),t[18]||(t[18]=o(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[15]||(t[15]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=o("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[19]||(t[19]=[o("LCTT",-1)])]),_:1}),t[22]||(t[22]=o(" 原創翻譯，",-1)),r(i,{href:"http://linux.cn/"},{default:l(()=>[...t[20]||(t[20]=[o("Linux中國",-1)])]),_:1}),t[23]||(t[23]=o(" 榮譽推出",-1))])])}const T=p(m,[["render",f]]);export{v as __pageData,T as default};
